    if (!buf || buf.length < 5) return false; // Minimum Modbus frame is 5 bytes (exception)
    const crc = calculateCRC(buf, buf.length - 2);
    const low = crc & 0xFF;
    const high = (crc >> 8) & 0xFF;
    return low === buf[buf.length - 2] && high === buf[buf.length - 1];
}

