function getBaseRegisters(bytes, startReg) {
    const regs = {};
    const buf = Buffer.from(bytes);
    for (let i = 0; i < 90; i++) {
        regs[startReg + i] = buf.readInt16BE(i * 2);
    }
    return regs;
}

// 1. Initialize or load current registers for all 3 blocks
let regsBlock1 = flow.get("lcd_config_registers_block1");
if (!regsBlock1) {
    regsBlock1 = getBaseRegisters(BASE_CONFIG_BYTES_1, 1001);
    flow.set("lcd_config_registers_block1", regsBlock1);
}

let regsBlock2 = flow.get("lcd_config_registers_block2");
if (!regsBlock2) {
    regsBlock2 = getBaseRegisters(BASE_CONFIG_BYTES_2, 1091);
    flow.set("lcd_config_registers_block2", regsBlock2);
}

let regsBlock3 = flow.get("lcd_config_registers_block3");
if (!regsBlock3) {
    regsBlock3 = getBaseRegisters(BASE_CONFIG_BYTES_3, 1181);
    flow.set("lcd_config_registers_block3", regsBlock3);
}

const input = msg.payload;

// 2. Command: Reset all 3 blocks to default
if (input === "reset") {
    regsBlock1 = getBaseRegisters(BASE_CONFIG_BYTES_1, 1001);
    regsBlock2 = getBaseRegisters(BASE_CONFIG_BYTES_2, 1091);
    regsBlock3 = getBaseRegisters(BASE_CONFIG_BYTES_3, 1181);
    flow.set("lcd_config_registers_block1", regsBlock1);
    flow.set("lcd_config_registers_block2", regsBlock2);
    flow.set("lcd_config_registers_block3", regsBlock3);
    flow.set("lcd_event_flag", 0);
    node.status({ fill: "blue", shape: "dot", text: "Reset all 3 blocks to defaults (Flag: 0)" });
    return [{ payload: { block1: regsBlock1, block2: regsBlock2, block3: regsBlock3 }, action: "reset", flag: 0 }, null];
}

// 3. Command: Query current configurations
if (input === "get") {
    const flag = flow.get("lcd_event_flag") ?? 0;
    const isInit = flow.get("lcd_config_initialized") === true;
    node.status({ fill: isInit ? "green" : "yellow", shape: "dot", text: `Configs queried (Init: ${isInit}, Flag: ${flag})` });
    return [{ payload: { initialized: isInit, flag: flag, block1: regsBlock1, block2: regsBlock2, block3: regsBlock3 }, action: "get" }, null];
}

// 4. Command: Trigger Flag 128 (Read-out all registers)
if (input === "read_all" || input === "flag_128" || input === "sync") {
    flow.set("lcd_config_initialized", false);
    flow.set("lcd_event_flag", 0x8000);
    flow.set("lcd_sync_status", "pending_flag_128");
    node.status({ fill: "yellow", shape: "dot", text: "Flag: 0x8000 (Queued Flag 128 read-out)" });
    return [{ payload: { flag: 0x8000, action: "read_all" }, flag: 0x8000 }, null];
}

// -------------------------------------------------------------------------
// SAFETY GUARD: Check if configuration has been read out via Flag 128
// -------------------------------------------------------------------------
const isInitialized = flow.get("lcd_config_initialized") === true;

// Command: Trigger Start (Flag 2)
if (input === "start" || input === "Start") {
    if (!isInitialized) {
        node.warn("Command blocked: Parameters have not been read out from Master via Flag 128 yet!");
        node.status({ fill: "red", shape: "ring", text: "Blocked: waiting for Flag 128 read-out" });
        return [null, {
            error: "CONFIGURATION_NOT_INITIALIZED",
            message: "Cannot trigger Start (Flag 2) until configuration is read out by Flag 128.",
            timestamp: new Date().toISOString()
        }];
    }
    flow.set("lcd_event_flag", 2);
    node.status({ fill: "green", shape: "dot", text: "Flag: 2 (Start command / Block 1)" });
    return [{ payload: { flag: 2, action: "start" }, flag: 2 }, null];
}

// 5. Update configuration: Input object e.g. { "1040": 52 }, { "1101": 150 }, or { "1191": 520 }
if (typeof input === "object" && input !== null) {
    if (!isInitialized) {
        node.warn("Configuration modification blocked: Parameters have not been read out from Master via Flag 128 yet!");
        node.status({ fill: "red", shape: "ring", text: "Blocked: waiting for Flag 128 read-out" });
        return [null, {
            error: "CONFIGURATION_NOT_INITIALIZED",
            message: "Writing values with Flag 2, 4, or 8 is not allowed until configuration is read out by Flag 128.",
            timestamp: new Date().toISOString(),
            rejectedInput: input
        }];
    }

    const modifiedB1 = {};
    const modifiedB2 = {};
    const modifiedB3 = {};

    for (const [key, val] of Object.entries(input)) {
        const regNum = parseInt(key, 10);
        if (isNaN(regNum)) continue;

        let intVal = parseInt(val, 10);
        if (isNaN(intVal)) intVal = 0;
        // Clamp to int16 (-32768 to 32767)
        if (intVal > 32767) intVal = 32767;
        if (intVal < -32768) intVal = -32768;

        if (regNum >= 1001 && regNum <= 1090) {
            regsBlock1[regNum] = intVal;
            modifiedB1[regNum] = intVal;
        } else if (regNum >= 1091 && regNum <= 1180) {
            regsBlock2[regNum] = intVal;
            modifiedB2[regNum] = intVal;
        } else if (regNum >= 1181 && regNum <= 1270) {
            regsBlock3[regNum] = intVal;
            modifiedB3[regNum] = intVal;
        }
    }

    const countB1 = Object.keys(modifiedB1).length;
    const countB2 = Object.keys(modifiedB2).length;
    const countB3 = Object.keys(modifiedB3).length;

    if (countB1 === 0 && countB2 === 0 && countB3 === 0) {
        node.status({ fill: "yellow", shape: "ring", text: "No valid registers in range 1001-1270" });
        return null;
    }

    // FLAG MAPPING:
    // - Block 1 (Reg 1001..1090) -> FLAG 2
    // - Block 2 (Reg 1091..1180) -> FLAG 4
    // - Block 3 (Reg 1181..1270) -> FLAG 8
    let determinedFlag = 2;
    if (msg.flag !== undefined) {
        determinedFlag = parseInt(msg.flag, 10);
    } else if (countB1 > 0 && countB2 === 0 && countB3 === 0) {
        determinedFlag = 2; // Flag 2 for Block 1 (1001..1090)
    } else if (countB2 > 0 && countB1 === 0 && countB3 === 0) {
        determinedFlag = 4; // Flag 4 for Block 2 (1091..1180)
    } else if (countB3 > 0 && countB1 === 0 && countB2 === 0) {
        determinedFlag = 8; // Flag 8 for Block 3 (1181..1270)
    } else if (countB2 > 0) {
        determinedFlag = 4;
    } else if (countB3 > 0) {
        determinedFlag = 8;
    } else {
        determinedFlag = 2;
    }

    flow.set("lcd_config_registers_block1", regsBlock1);
    flow.set("lcd_config_registers_block2", regsBlock2);
    flow.set("lcd_config_registers_block3", regsBlock3);
    flow.set("lcd_event_flag", determinedFlag);

    const changedSummary = [];
    if (countB1 > 0) changedSummary.push(`B1(Flag 2) [${Object.keys(modifiedB1).join(",")}]`);
    if (countB2 > 0) changedSummary.push(`B2(Flag 4) [${Object.keys(modifiedB2).join(",")}]`);
    if (countB3 > 0) changedSummary.push(`B3(Flag 8) [${Object.keys(modifiedB3).join(",")}]`);

    node.status({ fill: "green", shape: "dot", text: `Flag ${determinedFlag}: Updated ${changedSummary.join(" ")}` });

    return [
        {
            payload: {
                flag: determinedFlag,
                modifiedBlock1: modifiedB1,
                modifiedBlock2: modifiedB2,
                modifiedBlock3: modifiedB3,
                currentBlock1: regsBlock1,
                currentBlock2: regsBlock2,
                currentBlock3: regsBlock3
            },
            flag: determinedFlag
        },
        null
    ];
}

return null;

// --- Process incoming configuration change from Home Assistant ---
// Topic format: nodered/heatpump/nodered_heatpump_001/config/<reg>/set
// Payload: "ON", "OFF", "Heating", "50.0", "52", etc.
const topic = msg.topic || "";
const match = topic.match(/\/config\/(\d+)\/set$/);

if (!match) {
    node.warn(`Invalid HA config set topic: ${topic}`);
    return null;
}

const reg = parseInt(match[1], 10);
const registry = flow.get("hp_config_registry") || {};
const def = registry[reg];

if (!def) {
    node.warn(`Received command for unmapped register: ${reg}`);
    return null;
}

// Safety guard: Must be initialized via Flag 128
const isInitialized = flow.get("lcd_config_initialized") === true;
if (!isInitialized) {
    node.warn(`Change for Reg ${reg} blocked: Parameters not read out via Flag 128 yet!`);
    node.status({ fill: "red", shape: "ring", text: `Blocked Reg ${reg}: wait Flag 128` });
    return null;
}

const rawPayload = (msg.payload !== undefined && msg.payload !== null) ? msg.payload.toString().trim() : "";
let rawVal = 0;
let displayVal = rawPayload;

if (def.component === "switch") {
    const upper = rawPayload.toUpperCase();
    if (upper === "ON" || upper === "1" || upper === "TRUE") {
        rawVal = 1;
        displayVal = "ON";
    } else if (upper === "OFF" || upper === "0" || upper === "FALSE") {
        rawVal = 0;
        displayVal = "OFF";
    } else {
        node.warn(`Invalid switch payload for Reg ${reg} (${def.key}): "${rawPayload}"`);
        return null;
    }
} else if (def.component === "select") {
    const options = def.options || [];
    const optIdx = options.findIndex(o => o.toLowerCase() === rawPayload.toLowerCase());
    if (optIdx !== -1) {
        rawVal = optIdx;
        displayVal = options[optIdx];
    } else {
        const parsedIdx = parseInt(rawPayload, 10);
        if (!isNaN(parsedIdx) && parsedIdx >= 0 && parsedIdx < options.length) {
            rawVal = parsedIdx;
            displayVal = options[parsedIdx];
        } else {
            node.warn(`Invalid select payload for Reg ${reg} (${def.key}): "${rawPayload}". Options: ${options.join(", ")}`);
            return null;
        }
    }
} else {
    // Number component (default)
    let userVal = parseFloat(rawPayload);
    if (isNaN(userVal)) {
        node.warn(`Invalid numeric payload for Reg ${reg} (${def.key}): "${rawPayload}"`);
        return null;
    }

    // Clamp to configured min/max
    if (def.min !== undefined && userVal < def.min) userVal = def.min;
    if (def.max !== undefined && userVal > def.max) userVal = def.max;

    // Convert to raw Modbus register integer
    const scale = def.scale || 1;
    rawVal = Math.round(userVal / scale);
    displayVal = userVal;
}

// Map register to appropriate Flag / Block:
// - Block 1: Reg 1001..1090 -> Flag 2
// - Block 2: Reg 1091..1180 -> Flag 4
// - Block 3: Reg 1181..1270 -> Flag 8
let determinedFlag = 2;
if (reg >= 1001 && reg <= 1090) {
    determinedFlag = 2;
} else if (reg >= 1091 && reg <= 1180) {
    determinedFlag = 4;
} else if (reg >= 1181 && reg <= 1270) {
    determinedFlag = 8;
}

node.status({ fill: "green", shape: "dot", text: `Set Reg ${reg} (${def.key}) = ${displayVal} (Raw: ${rawVal}, Flag: ${determinedFlag})` });

// Pass to lcd_config_manager_01
return {
    payload: {
        [reg]: rawVal
    },
    flag: determinedFlag,
    source: "homeassistant",
    userValue: displayVal,
    register: reg
};

// --- Publish Heat Pump Configuration Registers to MQTT State ---
const baseTopic = "nodered/heatpump";
const deviceIdentifier = "nodered_heatpump_001";
const configStateTopic = `${baseTopic}/${deviceIdentifier}/config_state`;

// Ordered list from flow context to guarantee logical priority order (all 109 parameters)
const list = flow.get("hp_config_list") || [];

// Check if configuration has been read out from Master via Flag 128
const isInit = flow.get("lcd_config_initialized") === true;
if (!isInit) {
    node.status({ fill: "yellow", shape: "ring", text: "Waiting for Flag 128 init before publishing" });
    return null;
}

const b1 = flow.get("lcd_config_registers_block1") || {};
const b2 = flow.get("lcd_config_registers_block2") || {};
const b3 = flow.get("lcd_config_registers_block3") || {};

const statePayload = {};
let count = 0;

for (const def of list) {
    const reg = def.reg;
    let raw = null;
    if (reg >= 1001 && reg <= 1090) {
        raw = b1[reg];
    } else if (reg >= 1091 && reg <= 1180) {
        raw = b2[reg];
    } else if (reg >= 1181 && reg <= 1270) {
        raw = b3[reg];
    }

    if (raw !== undefined && raw !== null) {
        if (def.component === "switch") {
            const isStateOn = (raw === 1 || raw === "1" || raw === true);
            const stateStr = isStateOn ? "ON" : "OFF";
            statePayload[def.key] = stateStr;
            statePayload[def.key + "_num"] = isStateOn ? 1 : 0;
        } else if (def.component === "select") {
            const options = def.options || [];
            const optName = options[raw] !== undefined ? options[raw] : ("Option " + raw);
            statePayload[def.key] = raw;
            statePayload[def.key + "_name"] = optName;
        } else {
            // Number component
            const scale = def.scale || 1;
            const scaledVal = parseFloat((raw * scale).toFixed(2));
            statePayload[def.key] = scaledVal;
        }
        count++;
    }
}

if (count === 0) {
    node.status({ fill: "yellow", shape: "ring", text: "No registers loaded yet" });
    return null;
}

node.status({ fill: "green", shape: "dot", text: `Published ${count} config values to HA` });

return {
    topic: configStateTopic,
    payload: JSON.stringify(statePayload),
    retain: true
};
